/* Epu'ã offline copy. Generated by build.mjs: the file list, each file's hash, the sound files and the version are
 * filled in at build time.
 * Every file of the app is stored on the phone when this installs, and served from there afterwards,
 * so the app opens without a connection. A new build has a new version (a hash of the content of every file),
 * which replaces the stored copy. Each file is stored under a hash of its own content: the first install takes what
 * the browser has just downloaded for the page instead of downloading it again, and a new build downloads only the
 * files that changed (see fresh below). The sound files are stored when first used (see LAZY below). */
const VERSION = '3e3497c5b5';
/* the store is named after the folder this copy of the app lives in: a second copy under the same web
   address (a trial version, say) keeps its own store and never touches this one */
const HOME = new URL('./', self.location.href).pathname;
const PREFIX = 'epua:' + HOME + ':';
const CACHE = PREFIX + VERSION;
const FILES = [
 "./",
 "./assets/app.css",
 "./assets/build.js",
 "./assets/fonts.css",
 "./assets/fonts/epuatext-400.woff2",
 "./assets/fonts/epuatext-700.woff2",
 "./assets/fonts/nunito-500.woff2",
 "./assets/fonts/nunito-700.woff2",
 "./assets/fonts/nunito-800.woff2",
 "./assets/gn-app.js",
 "./assets/gn-course-a1.js",
 "./assets/gn-course-a2.js",
 "./assets/gn-course-b1.js",
 "./assets/gn-course-b2.js",
 "./assets/gn-course-c1.js",
 "./assets/gn-course-c2.js",
 "./assets/gn-course.js",
 "./assets/gn-extra.js",
 "./assets/gn-sound-index.js",
 "./assets/gn-sound.js",
 "./assets/gn-spell.js",
 "./assets/preact.min.js",
 "./assets/screens-more.js",
 "./assets/screens.css",
 "./assets/screens.js",
 "./assets/yk-runtime.js",
 "./icons/apple-touch-icon.png",
 "./icons/favicon-32.png",
 "./icons/icon-192-maskable.png",
 "./icons/icon-192.png",
 "./icons/icon-512-maskable.png",
 "./icons/icon-512.png",
 "./index.html",
 "./licenses.txt",
 "./manifest.webmanifest"
];
/* the first ten hex digits of the SHA-256 of each file's content, as the build made it (./ is the page, index.html) */
const HASH = {
 "./": "7675dc12cf",
 "./assets/app.css": "7c9a25ed0e",
 "./assets/build.js": "33eb780d11",
 "./assets/fonts.css": "44dc9ffc0f",
 "./assets/fonts/epuatext-400.woff2": "3926394b28",
 "./assets/fonts/epuatext-700.woff2": "14eec5dfbf",
 "./assets/fonts/nunito-500.woff2": "90e2d48816",
 "./assets/fonts/nunito-700.woff2": "622a9100d8",
 "./assets/fonts/nunito-800.woff2": "06145bc4f1",
 "./assets/gn-app.js": "a7fa45bfb7",
 "./assets/gn-course-a1.js": "d79e2d55f0",
 "./assets/gn-course-a2.js": "7f2fb81af8",
 "./assets/gn-course-b1.js": "a17ba303f3",
 "./assets/gn-course-b2.js": "b4a16c82b8",
 "./assets/gn-course-c1.js": "83d989ed0a",
 "./assets/gn-course-c2.js": "89e7ec56cd",
 "./assets/gn-course.js": "1a6c5b6db5",
 "./assets/gn-extra.js": "ee0880d89e",
 "./assets/gn-sound-index.js": "8e74fa0559",
 "./assets/gn-sound.js": "09f739bf8c",
 "./assets/gn-spell.js": "522c73fe5a",
 "./assets/preact.min.js": "25aa00978f",
 "./assets/screens-more.js": "72d208fd2f",
 "./assets/screens.css": "4f3dd4e360",
 "./assets/screens.js": "690c263b81",
 "./assets/yk-runtime.js": "af6c627d76",
 "./icons/apple-touch-icon.png": "94b30db31a",
 "./icons/favicon-32.png": "bba21c3c2d",
 "./icons/icon-192-maskable.png": "a2a4cb60b5",
 "./icons/icon-192.png": "43959e0c90",
 "./icons/icon-512-maskable.png": "194a19732e",
 "./icons/icon-512.png": "f2438193ee",
 "./index.html": "7675dc12cf",
 "./licenses.txt": "a65831a945",
 "./manifest.webmanifest": "5848ca0211"
};
const keyOf = (f) => f + '?v=' + HASH[f];
async function hashOf(res) {
  const sum = new Uint8Array(await crypto.subtle.digest('SHA-256', await res.clone().arrayBuffer()));
  let hex = '';
  for (let i = 0; i < 5; i++) hex += sum[i].toString(16).padStart(2, '0');
  return hex;
}
const isFile = async (res, f) => !!res && res.ok && (await hashOf(res)) === HASH[f];
/* A file of this build, checked against its hash: from the copy an earlier build stored, when its content is the same;
   else asked for at the address the page itself uses, in the browser's usual way, so a file the browser has just
   downloaded for the page is not downloaded twice. If what comes back is not this build's file (the browser, or the web
   host, still holds an older one), it is asked for again past every store, under this content's own address; if that is
   not it either, the install fails and the browser tries again later: a file of another build is never mixed in. */
async function fresh(olds, f) {
  for (const old of olds) {
    const kept = await old.match(keyOf(f));
    if (kept) return kept;
  }
  let res = await fetch(f).catch(() => null);
  if (await isFile(res, f)) return res;
  res = await fetch(new Request(keyOf(f), { cache: 'reload' }));
  if (await isFile(res, f)) return res;
  throw new Error('sw: ' + f + ' is not the file this build lists');
}
/* the course's sound, one file per unit (and one each for the placement check, a level's exam and the speaking game), is
   not part of the install (it would make the first download several times larger): a file is stored the first time the
   engine fetches it, and once there is a plan the app names the few files to have ahead (keepFiles, below): never a
   whole level. Each file carries a hash of its content, so a new build keeps the ones that did not change. */
const LAZY = {
 "./assets/gn-sound-a1-u01.js": "8a6b7556a6",
 "./assets/gn-sound-a1-u02.js": "1d04bb14e9",
 "./assets/gn-sound-a1-u03.js": "da5c086ef4",
 "./assets/gn-sound-a1-u04.js": "056ab59bfc",
 "./assets/gn-sound-a1-u05.js": "10bb2dfbf3",
 "./assets/gn-sound-a1-x.js": "9f1593717a",
 "./assets/gn-sound-pl.js": "ac1c4c140e",
 "./assets/gn-sound-sp.js": "6b43833bda"
};
const lazyKey = (f) => f + '?h=' + LAZY[f];
const lazyOf = (url) => { const p = './' + new URL(url).pathname.slice(HOME.length); return LAZY[p] ? p : null; };
const isLazy = async (res, f) => !!res && res.ok && (await hashOf(res)) === LAZY[f];
/* A sound file is fetched and stored once, however many ask for it at the same moment (the screen that needs it, and the
   app naming the files to keep). Like the files of the install, it is asked for at the address the page uses, in the
   browser's usual way: the file the page fetched before this worker was in charge (the first unit's, on a first visit)
   comes from the browser's own copy and is not downloaded a second time. What comes back must be this build's file;
   else it is asked for again past every copy, under its own hash, and a file of another build is not stored. */
const keeping = {};
const keepLazy = (cache, f) => keeping[f] || (keeping[f] = storeLazy(cache, f).finally(() => { delete keeping[f]; }));
async function storeLazy(cache, f) {
  if (await cache.match(lazyKey(f))) return;
  /* a copy already stored by an earlier build, if its content is the same */
  for (const k of await caches.keys()) {
    if (!k.startsWith(PREFIX) || k === CACHE) continue;
    const old = await (await caches.open(k)).match(lazyKey(f));
    if (old) { await cache.put(lazyKey(f), old); return; }
  }
  let res = await fetch(f).catch(() => null);
  if (!(await isLazy(res, f))) res = await fetch(new Request(lazyKey(f), { cache: 'reload' }));
  if (await isLazy(res, f)) await cache.put(lazyKey(f), res);
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then(async (cache) => {
        const olds = [];
        for (const k of await caches.keys()) if (k.startsWith(PREFIX) && k !== CACHE) olds.push(await caches.open(k));
        /* every file, each under its own hash; the same content is fetched once (the page is listed twice, as ./ and
           as index.html), and what an earlier try of this install stored is kept */
        const same = {};
        await Promise.all(FILES.map(async (f) => {
          if (await cache.match(keyOf(f))) return;
          const got = same[HASH[f]] || (same[HASH[f]] = fresh(olds, f));
          await cache.put(keyOf(f), (await got).clone());
        }));
        /* the sound files of earlier builds that are unchanged come along (nothing new is downloaded here) */
        if (olds.length) {
          for (const f of Object.keys(LAZY)) {
            for (const old of olds) {
              const res = await old.match(lazyKey(f));
              if (res) { await cache.put(lazyKey(f), res); break; }
            }
          }
        }
      })
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  /* a sound file: from the store, or fetched and stored now, so it is there offline from then on */
  const lazy = lazyOf(request.url);
  if (lazy) {
    event.respondWith(
      caches.open(CACHE)
        .then(async (cache) => (await cache.match(lazyKey(lazy))) || (await keepLazy(cache, lazy), await cache.match(lazyKey(lazy))) || fetch(request))
        .catch(() => fetch(request))
    );
    return;
  }
  event.respondWith(
    caches.open(CACHE)
      .then(async (cache) => {
        const stored = await cache.match(request, { ignoreSearch: true });
        if (stored) return stored;
        /* opening the app by any address in its own folder gets the app's one page; an address in a folder
           below it belongs to something else kept there and goes to the network */
        if (request.mode === 'navigate') {
          const path = new URL(request.url).pathname;
          if (path.startsWith(HOME) && !path.slice(HOME.length).includes('/')) {
            const page = await cache.match('./index.html', { ignoreSearch: true });
            if (page) return page;
          }
        }
        return fetch(request);
      })
      /* the store could not be opened: fall back to the network */
      .catch(() => fetch(request))
  );
});

/* The app names the sound files to store (keepFiles), in the order it wants them, once there is a plan: those the page
   has asked for itself (the one it fetched before this worker was in charge, the first unit's on a first visit, comes
   from the browser's own copy), and the few it wants ahead of time for use without a connection: the unit in use, the
   one after it, the speaking game (gn-app.js, keepSound; none ahead for a learner whose browser says they save
   data). Only the files named are stored, one after the other: a whole level is never fetched behind the learner's
   back (a worker of an earlier build took the level's name, keepLevel, and fetched all of it: that message is no
   longer understood). A file asked for later passes through this worker and is stored then. */
self.addEventListener('message', (event) => {
  const data = event.data || {};
  if (!Array.isArray(data.keepFiles)) return;
  const all = Object.keys(LAZY);
  const mine = [];
  data.keepFiles.forEach((name) => { const f = all.find((x) => x.split('/').pop() === name); if (f && mine.indexOf(f) < 0) mine.push(f); });
  if (!mine.length) return;
  event.waitUntil(caches.open(CACHE).then(async (cache) => { for (const f of mine) { try { await keepLazy(cache, f); } catch (e) { /* offline: try again next time */ } } }));
});
